"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7336],{7336:n=>{n.exports=JSON.parse('{"id":"base-02","slug":"base-02","trackId":"base","order":3,"title":"Безопасность прежде всего","subtitle":"Понятные правила защиты капитала","estimatedMinutes":7,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-08"],"markdown":"Урок 2 \xb7 4 мин \\n\\n## Безопасность \\n\\nБезопасность прежде всего — все хотят тебя обмануть \\n\\nКриптовалюта даёт человеку больше контроля над своими деньгами. Но вместе с этим — и больше ответственности. Если в банке украли данные карты, иногда можно заблокировать операцию, вернуть деньги или обратиться в поддержку. В криптовалюте всё часто работает иначе. \\n\\nЕсли ты сам отправил средства мошеннику, подписал вредоносную транзакцию или отдал кому-то доступ к кошельку, вернуть деньги может быть уже невозможно. Поэтому первое правило простое: \\n\\nсначала безопасность — потом всё остальное. \\n\\n### Почему в крипте так много мошенников \\n\\nПричина проста: деньги можно переводить быстро, напрямую и часто без возможности отменить операцию. Мошеннику не обязательно взламывать блокчейн. Гораздо проще обмануть тебя. Убедить перейти по поддельной ссылке. \\n\\nПредставиться сотрудником поддержки. Пообещать лёгкие деньги. Попросить seed-фразу от кошелька. Или сыграть на страхе и жадности. \\n\\nПоэтому большая часть мошенничества в крипте направлена не на технологии, а на человека. \\n\\n### Не верь сообщениям в личке \\n\\nПредставь: у тебя возникла проблема с кошельком, ты написал об этом в Telegram или Discord, и через несколько минут тебе пишет \xabсотрудник поддержки\xbb. Очень вероятно, что это мошенник. Он может использовать логотип проекта, похожее имя и даже фотографию настоящего сотрудника. Дальше тебя попросят перейти по ссылке, подключить кошелёк или ввести данные. \\n\\nПоэтому если кто-то первым пишет тебе в личку — относись к этому как к потенциальному мошенничеству. \\n\\n### Известный человек — не гарантия \\n\\nБольшое количество подписчиков ничего не гарантирует. Аккаунт можно взломать. Видео — подделать. Telegram-канал — скопировать. \\n\\nПоэтому фраза \xabэто же написал известный человек\xbb сама по себе ничего не доказывает. Если кто-то предлагает отправить деньги, подключить кошелёк или срочно что-то купить — сделай паузу и проверь информацию. \\n\\n### Проверяй сайт \\n\\nПоддельные сайты могут выглядеть почти идентично настоящим. Та же картинка. Тот же логотип. Те же кнопки. \\n\\nРазница иногда всего в одной букве в адресе. Поэтому особенно внимательно относись к ссылкам из Telegram, Discord, комментариев, рекламы, писем и личных сообщений. Необходимо открывать известные сервисы через официальный сайт или заранее сохранённую закладку. \\n\\n### Бесплатные деньги почти никогда не бывают бесплатными \\n\\nВ крипте постоянно встречаются сообщения вроде: \\n\\n\xabВы выиграли токены\xbb \\n\\nЕсли предложение выглядит слишком хорошим, чтобы быть правдой, скорее всего, это обман. Особенно если тебя торопят: \\n\\n\xabТолько сегодня\xbb. \xabОсталось 10 минут\xbb. \xabЕсли не заберёшь сейчас — потеряешь награду\xbb. Цель одна — заставить тебя перестать думать и начать действовать. \\n\\n### Не спеши \\n\\nБольшинство мошеннических схем пытаются создать срочность. Если речь идёт о деньгах, спешка почти никогда не помогает. Перед действием: \\n- остановись, включи критическое мышление \\n- дай себе время всё обдумать \\n- убедись, что понимаешь происходящее. \\n- ещё раз проверь сайт; \\n- проверь, кому отправляешь деньги; \\n- прочитай, что подтверждаешь; \\n\\nПять минут проверки могут сохранить тебе все деньги. \\n\\n### Никто не должен знать твою seed-фразу \\n\\nSeed-фраза — это главный ключ к твоему кошельку. Обычно она состоит из 12 или 24 слов. Тот, кто получил эту фразу, фактически получил полный контроль над твоими средствами. Неважно, кем человек представился: поддержкой, администратором проекта или известным блогером. \\n\\nНикому не отправляй seed-фразу. Никогда. \\n\\nНастоящая поддержка никогда её не запросит. \\n\\n### Проверяй адрес перед переводом \\n\\nКриптовалютные адреса длинные и выглядят примерно так: \\n\\n0x71C...8F3A \\n\\nЛюди обычно копируют их, и здесь легко ошибиться. Можно вставить не тот адрес или случайно отправить средства другому человеку. Поэтому перед переводом сверяй символы адреса. Лучше не использовать быстрый доступ к “недавним адресам” для повторных переводов, а делать всё вручную. Контролируйте процесс. \\n\\nМошенники регулярно рассылают транзакции по адресам с целью попасть в список адресов, с которыми вы якобы взаимодействовали. Если отправляешь крупную сумму впервые — сначала переведи небольшую тестовую сумму. \\n\\n### Не подписывай то, чего не понимаешь \\n\\nИногда кошелёк просит не отправить деньги, а просто что-то \xabподписать\xbb. Это может выглядеть безобидно. Но такая подпись может дать приложению определённые права на взаимодействие с твоими активами. Если ты не понимаешь, что за сайт, зачем он просит подтверждение и какие права ты даёшь — лучше ничего не подтверждать. \\n\\n### В крипте никто не вернёт тебе деньги \\n\\nЕсли ты сам подтвердил перевод на неправильный адрес, банк не сможет нажать кнопку \xabотменить\xbb. Если передал мошеннику доступ к кошельку, компенсировать потери некому. Поэтому главное правило безопасности здесь другое: \\n\\nбыть бдительным и никому не доверять \\n\\nБезопасно или развод? Семь ситуаций \\n\\nПожаловался на кошелёк в чате — через минуту в личку пишет \xabподдержка\xbb \\n\\n### Главное, что стоит запомнить \\n- никому не сообщай seed-фразу; \\n- не переходи по подозрительным ссылкам; \\n- не доверяй незнакомцам, которые сами пишут тебе в личку; \\n- проверяй адрес сайта и получателя; \\n- не подтверждай действия, которых не понимаешь; \\n- не верь обещаниям гарантированной доходности и бесплатных денег; \\n- при крупном переводе сначала отправь тестовую сумму; \\n- не принимай финансовые решения в спешке. \\n\\nИ главное: \\n\\nв крипте не нужно быть параноиком. Нужно просто привыкнуть проверять. \\n\\nВ следующей статье разберём, как правильно хранить криптовалюту и что представляет собой криптовалютный кошелёк. \\n\\n### Проверь себя 1 / 3 \\n\\nЧеловек из поддержки пишет тебе первым и просит seed-фразу, чтобы восстановить кошелёк. Что делать? \\n\\n\\n### Встроенные термины урока:\\n- **Блокчейн** — таблица всех транзакций, которую видят все: добавить запись можно, изменить старую нельзя. Хранится одновременно на миллионах компьютеров, поэтому подделать историю физически невозможно\\n- **Доходность** — сколько процентов в год на самом деле приносит вложение при сегодняшней цене. У облигации цена и доходность ходят в разные стороны: облигация дешевеет — доходность растёт. От доходности гособлигаций отталкиваются ставки по кредитам и вкладам\\n- **Сид-фраза** — 12 или 24 слова, из которых восстанавливается кошелёк. У кого фраза — у того и деньги, поэтому её не просит ни поддержка, ни администратор проекта\\n- **Токен** — цифровой актив, который существует внутри какой-то сети, например USDT или USDC. Один и тот же токен бывает в разных сетях, и это разные его версии\\n\\n### Проверочный тест после урока (\xabПроверь себя\xbb):\\n**Вопрос 1: Человек из поддержки пишет тебе первым и просит seed-фразу, чтобы восстановить кошелёк. Что делать?**\\n- ⚪ Вариант 1: Передать фразу, если аккаунт поддержки выглядит официально\\n- ⚪ Вариант 2: Передать только половину слов\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 3: Никому не передавать seed-фразу\\n\\n**Вопрос 2: Тебя просят срочно перейти по ссылке и подтвердить операцию, иначе \xabденьги пропадут через 10 минут\xbb. Что безопаснее всего сделать?**\\n- ⚪ Вариант 1: Быстро подтвердить, пока не истёк срок\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Остановиться и отдельно проверить сайт, информацию и само действие\\n- ⚪ Вариант 3: Переслать ссылку другу и, если она открывается, подтвердить\\n\\n**Вопрос 3: Почему мошенникам часто проще обмануть пользователя, чем взломать сам блокчейн?**\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 1: Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию\\n- ⚪ Вариант 2: Потому что блокчейн вообще не защищён\\n- ⚪ Вариант 3: Потому что все криптокошельки используют одинаковые пароли\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-02-1","prompt":"Человек из поддержки пишет тебе первым и просит seed-фразу, чтобы восстановить кошелёк. Что делать?","options":[{"id":"base-02-1-1","label":"Передать фразу, если аккаунт поддержки выглядит официально","isCorrect":false,"feedback":"Неверно. Никому не передавать seed-фразу"},{"id":"base-02-1-2","label":"Передать только половину слов","isCorrect":false,"feedback":"Неверно. Никому не передавать seed-фразу"},{"id":"base-02-1-3","label":"Никому не передавать seed-фразу","isCorrect":true,"feedback":"Верно. Никому не передавать seed-фразу"}],"explanation":"Никому не передавать seed-фразу","sourceRef":"CAPITAL_BASE:451–454 (Verbatim)"},{"id":"q-base-02-2","prompt":"Тебя просят срочно перейти по ссылке и подтвердить операцию, иначе \xabденьги пропадут через 10 минут\xbb. Что безопаснее всего сделать?","options":[{"id":"base-02-2-1","label":"Быстро подтвердить, пока не истёк срок","isCorrect":false,"feedback":"Неверно. Остановиться и отдельно проверить сайт, информацию и само действие"},{"id":"base-02-2-2","label":"Остановиться и отдельно проверить сайт, информацию и само действие","isCorrect":true,"feedback":"Верно. Остановиться и отдельно проверить сайт, информацию и само действие"},{"id":"base-02-2-3","label":"Переслать ссылку другу и, если она открывается, подтвердить","isCorrect":false,"feedback":"Неверно. Остановиться и отдельно проверить сайт, информацию и само действие"}],"explanation":"Остановиться и отдельно проверить сайт, информацию и само действие","sourceRef":"CAPITAL_BASE:456–459 (Verbatim)"},{"id":"q-base-02-3","prompt":"Почему мошенникам часто проще обмануть пользователя, чем взломать сам блокчейн?","options":[{"id":"base-02-3-1","label":"Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию","isCorrect":true,"feedback":"Верно. Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию"},{"id":"base-02-3-2","label":"Потому что блокчейн вообще не защищён","isCorrect":false,"feedback":"Неверно. Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию"},{"id":"base-02-3-3","label":"Потому что все криптокошельки используют одинаковые пароли","isCorrect":false,"feedback":"Неверно. Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию"}],"explanation":"Потому что пользователь может сам передать доступ или подтвердить вредоносную операцию","sourceRef":"CAPITAL_BASE:461–464 (Verbatim)"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":325,"lineEnd":469}}')}}]);